35	bool engineHasIOTensor(nvinfer1::ICudaEngine const& engine, char const* tensorName)
36	{
37	    if (tensorName == nullptr)
38	    {
39	        return false;
40	    }
41	
42	    int32_t const numIO = engine.getNbIOTensors();
43	    for (int32_t i = 0; i < numIO; ++i)
44	    {
45	        char const* const name = engine.getIOTensorName(i);
46	        if (name != nullptr && std::string_view{name} == tensorName)
47	        {
48	            return true;
49	        }
50	    }
51	    return false;
52	}
53	
54	bool engineHasInputTensor(nvinfer1::ICudaEngine const& engine, char const* tensorName)
55	{
56	    if (tensorName == nullptr)
57	    {
58	        return false;
59	    }
60	
61	    int32_t const numIO = engine.getNbIOTensors();
62	    for (int32_t i = 0; i < numIO; ++i)
63	    {
64	        char const* const name = engine.getIOTensorName(i);
65	        if (name != nullptr && std::string_view{name} == tensorName)
66	        {
67	            return engine.getTensorIOMode(name) == nvinfer1::TensorIOMode::kINPUT;
68	        }
69	    }
70	    return false;
71	}
