74	EngineExecutor::EngineExecutor(std::filesystem::path const& enginePath, TensorRegistry registry)
75	    : mRegistry(std::move(registry))
76	{
77	    LOG_INFO("loading engine file: %s", enginePath.string().c_str());
78	
79	    mRuntime = std::unique_ptr<nvinfer1::IRuntime>(nvinfer1::createInferRuntime(gLogger));
80	    ELLM_CHECK(mRuntime != nullptr, "failed to create TRT IRuntime");
81	
82	    mEngine = deserializeCudaEngineFromFile(*mRuntime, enginePath);
83	
84	    // Use USER_MANAGED allocation so context memory can be shared across runners.
85	    mContext = std::unique_ptr<nvinfer1::IExecutionContext>(
86	        mEngine->createExecutionContext(nvinfer1::ExecutionContextAllocationStrategy::kUSER_MANAGED));
87	    ELLM_CHECK(mContext != nullptr, "failed to create execution context");
88	
89	    setNonBlockingAuxStreams(mContext.get(), mEngine.get(), mAuxStreams);
90	
91	    auto registerOptionalTreeMetadata = [&](char const* name) {
92	        if (engineHasInputTensor(*mEngine, name) && !mRegistry.contains(name))
93	        {
94	            mRegistry.addTensor({name, TensorIO::kInput, nvinfer1::DataType::kINT32,
95	                {sym(&InferenceDims::batch), sym(&InferenceDims::attnMaskSeqLen)}});
96	        }
97	    };
98	    registerOptionalTreeMetadata(binding_names::kTreeParentIds);
99	    registerOptionalTreeMetadata(binding_names::kTreeDepths);
100	
101	    LOG_INFO("engine loaded successfully (%d I/O tensors)", mEngine->getNbIOTensors());
102	}
103	
104	std::unique_ptr<EngineExecutor> EngineExecutor::createForLLM(std::filesystem::path const& enginePath,
105	    LLMEngineConfig const& cfg, std::optional<int32_t> specDecodeBaseOutputHiddenDim)
106	{
107	    auto registry = buildRegistryForLLM(cfg, specDecodeBaseOutputHiddenDim);
108	    return std::unique_ptr<EngineExecutor>(new EngineExecutor(enginePath, std::move(registry)));
109	}
110	
111	std::unique_ptr<EngineExecutor> EngineExecutor::createForDraft(
112	    std::filesystem::path const& enginePath, DeploymentConfig const& bundle)
113	{
114	    switch (bundle.specDecodeMode())
115	    {
116	    case SpecDecodeMode::kMTP:
117	    case SpecDecodeMode::kEAGLE:
118	    {
119	        auto registry = buildRegistryForSpecDecodeDraft(bundle);
120	        return std::unique_ptr<EngineExecutor>(new EngineExecutor(enginePath, std::move(registry)));
121	    }
122	    case SpecDecodeMode::kDFlash:
123	    {
124	        auto registry = buildRegistryForDFlashDraft(bundle);
125	        return std::unique_ptr<EngineExecutor>(new EngineExecutor(enginePath, std::move(registry)));
126	    }
127	    case SpecDecodeMode::kGemma4MTP:
128	    {
129	        auto registry = buildRegistryForGemma4MTPDraft(bundle);
130	        return std::unique_ptr<EngineExecutor>(new EngineExecutor(enginePath, std::move(registry)));
131	    }
132	    case SpecDecodeMode::kNONE:
133	    default: ELLM_CHECK(false, "createForDraft requires a speculative decoding deployment with a draft engine.");
134	    }
135	    return nullptr;
136	}
