138	EngineExecutor::~EngineExecutor() noexcept
139	{
140	    for (auto& [hash, cg] : mGraphs)
141	    {
142	        if (cg.exec)
143	        {
144	            cudaGraphExecDestroy(cg.exec);
145	        }
146	        if (cg.graph)
147	        {
148	            cudaGraphDestroy(cg.graph);
149	        }
150	    }
151	    mGraphs.clear();
152	}
