154	bool EngineExecutor::prepare(int32_t profileIndex, InferenceDims const& dims, TensorMap const& map, cudaStream_t stream)
155	{
156	    if (auto bad = firstInvalidMember(dims, mRegistry.referencedMembers()); bad != nullptr)
157	    {
158	        auto const name = dimName(bad);
159	        LOG_ERROR(
160	            "EngineExecutor::prepare: InferenceDims.%.*s = %lld (must be > 0); "
161	            "caller likely bypassed an LLMEngineConfig recipe method",
162	            static_cast<int>(name.size()), name.data(), static_cast<long long>(dims.*bad));
163	        return false;
164	    }
165	
166	    if (!mContext->setOptimizationProfileAsync(profileIndex, stream))
167	    {
168	        LOG_ERROR("failed to set optimization profile %d", profileIndex);
169	        return false;
170	    }
171	
172	    if (!mRegistry.bindAll(mContext.get(), map, dims))
173	    {
174	        LOG_ERROR("bindAll failed for profile %d", profileIndex);
175	        return false;
176	    }
177	
178	    // Bind any TensorMap entries not covered by the registry. We rebind
179	    // address+shape on every call (not just when getTensorAddress is null)
180	    // because TRT does NOT clear bindings on setOptimizationProfileAsync —
181	    // shapes and addresses persist across profile switches and across
182	    // execute() calls. Unregistered tensors that change shape per step
183	    // (notably kvcache_start_index, which uses [0] for initial prefill and
184	    // [batch] for chunked prefill / decode) would otherwise stick at
185	    // whatever shape was set by the previous step.
186	    //
187	    // LoRA weights are model-dependent and populated into the TensorMap by
188	    // LoRAManager::refreshTensorMap() before prepare() is called.
189	    int32_t const numIO = mEngine->getNbIOTensors();
190	    for (int32_t i = 0; i < numIO; ++i)
191	    {
192	        char const* name = mEngine->getIOTensorName(i);
193	        if (mRegistry.contains(name))
194	        {
195	            // Already bound by bindAll above; leave alone.
196	            continue;
197	        }
198	        Tensor* tensor = map.get(name);
199	        if (tensor == nullptr)
200	        {
201	            LOG_ERROR(
202	                "engine binding '%s' is neither registry-bound nor present in the TensorMap; "
203	                "every engine I/O tensor must be handled by the registry, by LoRAManager, or by an explicit "
204	                "TensorMap entry. Most likely the runtime is missing a binding for a model variant.",
205	                name);
206	            return false;
207	        }
208	        if (!mContext->setTensorAddress(name, tensor->rawPointer()))
209	        {
210	            LOG_ERROR("setTensorAddress failed for binding '%s'", name);
211	            return false;
212	        }
213	        if (mEngine->getTensorIOMode(name) == nvinfer1::TensorIOMode::kINPUT)
214	        {
215	            if (!mContext->setInputShape(name, tensor->getTRTDims()))
216	            {
217	                LOG_ERROR("setInputShape failed for binding '%s'", name);
218	                return false;
219	            }
220	        }
221	    }
222	
223	    return true;
224	}
225	
226	bool EngineExecutor::execute(cudaStream_t stream)
227	{
228	    size_t const hash = computeBindingHash();
229	    auto it = mGraphs.find(hash);
230	    if (it != mGraphs.end())
231	    {
232	        BindingSnapshot const current = snapshotBindings();
233	        if (current == it->second.snapshot)
234	        {
235	            cudaError_t const err = cudaGraphLaunch(it->second.exec, stream);
236	            if (err == cudaSuccess)
237	            {
238	                return true;
239	            }
240	            LOG_WARNING("cudaGraphLaunch failed (%s), falling back to enqueueV3", cudaGetErrorString(err));
241	        }
242	    }
243	
244	    return mContext->enqueueV3(stream);
245	}
246	
247	bool EngineExecutor::captureGraph(cudaStream_t stream)
248	{
249	    // Warmup: run one enqueue to ensure all internal TRT state is initialized.
250	    if (!mContext->enqueueV3(stream))
251	    {
252	        LOG_ERROR("warmup enqueueV3 failed");
253	        return false;
254	    }
255	    CUDA_CHECK(cudaStreamSynchronize(stream));
256	
257	    auto result = captureTRTCudaGraph(mContext.get(), stream);
258	    if (!result.has_value())
259	    {
260	        LOG_WARNING("CUDA graph capture failed");
261	        return false;
262	    }
263	
264	    size_t const hash = computeBindingHash();
265	    BindingSnapshot const snap = snapshotBindings();
266	
267	    // If there was a previous graph for this hash, destroy it first.
268	    auto it = mGraphs.find(hash);
269	    if (it != mGraphs.end())
270	    {
271	        if (it->second.exec)
272	        {
273	            cudaGraphExecDestroy(it->second.exec);
274	        }
275	        if (it->second.graph)
276	        {
277	            cudaGraphDestroy(it->second.graph);
278	        }
279	    }
280	
281	    CapturedGraph cg{};
282	    cg.graph = result->first;
283	    cg.exec = result->second;
284	    cg.snapshot = snap;
285	    mGraphs[hash] = cg;
286	
287	    LOG_INFO("captured graph (hash=0x%zx)", hash);
288	    return true;
289	}
