291	int64_t EngineExecutor::getRequiredContextMemorySize() const
292	{
293	    // Use getDeviceMemorySizeV2() to get the max across ALL profiles.
294	    // SpecDecode base engines have multiple profiles (prefill + verification) with
295	    // different memory requirements. Using per-profile size can underallocate.
296	    return mEngine->getDeviceMemorySizeV2();
297	}
