331	void EngineExecutor::setProfiler(nvinfer1::IProfiler* profiler) noexcept
332	{
333	    mContext->setProfiler(profiler);
334	}
335	
336	nvinfer1::ICudaEngine const& EngineExecutor::getEngine() const noexcept
337	{
338	    return *mEngine;
339	}
340	
341	// ---------------------------------------------------------------------------
342	// BindingSnapshot
343	// ---------------------------------------------------------------------------
344	
345	bool EngineExecutor::BindingSnapshot::operator==(BindingSnapshot const& rhs) const noexcept
346	{
347	    if (bindings.size() != rhs.bindings.size())
348	    {
349	        return false;
350	    }
351	    for (size_t i = 0; i < bindings.size(); ++i)
352	    {
353	        if (bindings[i].first != rhs.bindings[i].first)
354	        {
355	            return false;
356	        }
357	        if (!dimsEqual(bindings[i].second, rhs.bindings[i].second))
358	        {
359	            return false;
360	        }
361	    }
362	    return true;
363	}
364	
365	// ---------------------------------------------------------------------------
366	// Private helpers
367	// ---------------------------------------------------------------------------
368	
369	size_t EngineExecutor::computeBindingHash() const
370	{
371	    size_t seed = 0;
372	    int32_t const numIO = mEngine->getNbIOTensors();
373	    for (int32_t i = 0; i < numIO; ++i)
374	    {
375	        char const* name = mEngine->getIOTensorName(i);
376	        auto const addr = reinterpret_cast<uintptr_t>(mContext->getTensorAddress(name));
377	        nvinfer1::Dims const shape = mContext->getTensorShape(name);
378	
379	        hash_utils::hashCombine(seed, addr);
380	        hash_utils::hashCombine(seed, shape.nbDims);
381	        for (int32_t d = 0; d < shape.nbDims; ++d)
382	        {
383	            hash_utils::hashCombine(seed, shape.d[d]);
384	        }
385	    }
386	    return seed;
387	}
388	
389	EngineExecutor::BindingSnapshot EngineExecutor::snapshotBindings() const
390	{
391	    BindingSnapshot snap;
392	    int32_t const numIO = mEngine->getNbIOTensors();
393	    snap.bindings.reserve(numIO);
394	    for (int32_t i = 0; i < numIO; ++i)
395	    {
396	        char const* name = mEngine->getIOTensorName(i);
397	        auto const addr = reinterpret_cast<uintptr_t>(mContext->getTensorAddress(name));
398	        nvinfer1::Dims const shape = mContext->getTensorShape(name);
399	        snap.bindings.emplace_back(addr, shape);
400	    }
401	    return snap;
402	}
403	
