29	
30	void TensorRegistry::addTensor(TensorSpec spec)
31	{
32	    // Catch spec authoring mistakes at registration time, not at the first bindAll:
33	    // resolveShape writes into nvinfer1::Dims::d[MAX_DIMS] (fixed-size 8). Today all
34	    // specs are 5D or fewer, but checking here means a future TensorSpec with too many
35	    // dims fails loud at construction instead of silently corrupting the stack.
36	    ELLM_CHECK(spec.shape.size() <= static_cast<size_t>(nvinfer1::Dims::MAX_DIMS),
37	        "TensorRegistry::addTensor: spec '" + spec.name + "' has " + std::to_string(spec.shape.size())
38	            + " dims, exceeds nvinfer1::Dims::MAX_DIMS=" + std::to_string(nvinfer1::Dims::MAX_DIMS));
39	    mSpecs.push_back(std::move(spec));
40	    mDirty = true;
41	}
42	
43	std::vector<TensorSpec> TensorRegistry::expandPerLayer(TensorSpec const& spec) const
44	{
45	    std::vector<TensorSpec> result;
46	    if (spec.perLayer <= 0)
47	    {
48	        result.push_back(spec);
49	        result.back().perLayer = 0;
50	        return result;
51	    }
52	    for (int32_t i = 0; i < spec.perLayer; ++i)
53	    {
54	        TensorSpec expanded = spec;
55	        char buf[256];
56	        std::snprintf(buf, sizeof(buf), spec.name.c_str(), i);
57	        expanded.name = buf;
58	        expanded.perLayer = 0;
59	        result.push_back(std::move(expanded));
60	    }
61	    return result;
62	}
63	
64	std::vector<TensorSpec> const& TensorRegistry::allExpandedSpecs() const
65	{
66	    if (mDirty)
67	    {
68	        mExpandedSpecs.clear();
69	        mReferencedMembers.clear();
70	        for (auto const& spec : mSpecs)
71	        {
72	            auto expanded = expandPerLayer(spec);
73	            mExpandedSpecs.insert(mExpandedSpecs.end(), expanded.begin(), expanded.end());
74	        }
75	        // `std::hash` has no specialization for pointer-to-member, so dedupe via
76	        // a linear scan. The working set is small (≤6 LLM symbolic dims).
77	        for (auto const& spec : mExpandedSpecs)
78	        {
79	            for (auto const& dim : spec.shape)
80	            {
81	                if (dim.isSymbolic()
82	                    && std::find(mReferencedMembers.begin(), mReferencedMembers.end(), dim.symbol)
83	                        == mReferencedMembers.end())
84	                {
85	                    mReferencedMembers.push_back(dim.symbol);
86	                }
87	            }
88	        }
89	        mDirty = false;
90	    }
91	    return mExpandedSpecs;
92	}
93	
94	std::vector<int64_t InferenceDims::*> const& TensorRegistry::referencedMembers() const
95	{
96	    // allExpandedSpecs() populates mReferencedMembers as a side-effect when mDirty.
97	    (void) allExpandedSpecs();
98	    return mReferencedMembers;
99	}
100	
101	std::vector<std::string> TensorRegistry::allTensorNames() const
102	{
103	    std::vector<std::string> names;
104	    for (auto const& spec : allExpandedSpecs())
105	    {
106	        names.push_back(spec.name);
107	    }
108	    return names;
109	}
110	
111	bool TensorRegistry::contains(std::string_view name) const
112	{
113	    for (auto const& spec : allExpandedSpecs())
114	    {
115	        if (spec.name == name)
116	        {
117	            return true;
118	        }
119	    }
120	    return false;
121	}
122	
123	nvinfer1::Dims TensorRegistry::resolveShape(
124	    std::vector<ShapeDim> const& shape, InferenceDims const& inferenceDims) const
125	{
126	    nvinfer1::Dims dims;
127	    dims.nbDims = static_cast<int32_t>(shape.size());
128	    for (int32_t i = 0; i < dims.nbDims; ++i)
129	    {
130	        dims.d[i] = shape[i].isSymbolic() ? inferenceDims.*(shape[i].symbol) : shape[i].value;
131	    }
132	    return dims;
133	}
134	
135	bool TensorRegistry::bindAll(
136	    nvinfer1::IExecutionContext* ctx, TensorMap const& tensorMap, InferenceDims const& inferenceDims) const
137	{
138	    bool success = true;
139	    for (auto const& spec : allExpandedSpecs())
140	    {
141	        Tensor* tensor = tensorMap.get(spec.name);
142	        if (!tensor)
143	        {
144	            LOG_ERROR("tensor '%s' not in tensorMap", spec.name.c_str());
145	            success = false;
146	            continue;
147	        }
148	        if (!ctx->setTensorAddress(spec.name.c_str(), tensor->rawPointer()))
149	        {
150	            LOG_ERROR("setTensorAddress failed for '%s'", spec.name.c_str());
151	            success = false;
152	            continue;
153	        }
154	        if (spec.io == TensorIO::kInput)
155	        {
156	            // Resolve the input shape from symbolic dimensions. This is necessary
157	            // because some tensors (e.g. KV cache) are allocated at maxBatchSize
158	            // but need their input shape set to activeBatchSize for TRT execution.
159	            // Tensors with all-fixed shapes are returned as-is.
160	            auto dims = resolveShape(spec.shape, inferenceDims);
161	            if (!ctx->setInputShape(spec.name.c_str(), dims))
162	            {
163	                LOG_ERROR("setInputShape failed for '%s'", spec.name.c_str());
164	                success = false;
165	            }
166	        }
167	    }
168	    return success;
169	}
