17	
18	#include "runtime/exec/registryBuilder.h"
19	#include "common/bindingNames.h"
20	#include "common/checkMacros.h"
21	
22	namespace trt_edgellm
23	{
24	namespace rt
25	{
26	
27	// Note: `sym(...)` and `fixed(...)` helpers are now provided by inferenceDims.h.
28	// Symbolic-dim registration (formerly `addCommonSymbolicDims` / `addSymbolicDim`)
29	// is no longer needed — every symbolic reference is a pointer-to-member of
30	// `InferenceDims`, so the set of dims exists by construction of the type.
31	
32	void addRopeTensorSpecs(TensorRegistry& reg, LLMEngineConfig const& cfg)
33	{
34	    auto addRopeTensor = [&](char const* name, int32_t rotaryDim) {
35	        reg.addTensor({name, TensorIO::kInput, nvinfer1::DataType::kFLOAT,
36	            {sym(&InferenceDims::ropeBatch), sym(&InferenceDims::kvLen), fixed(rotaryDim)}});
37	    };
38	
39	    if (cfg.useDualRope)
40	    {
41	        addRopeTensor(binding_names::kRopeCosSinSliding, cfg.slidingRotaryDim);
42	        addRopeTensor(binding_names::kRopeCosSinFull, cfg.fullRotaryDim);
43	        return;
44	    }
45	
46	    addRopeTensor(binding_names::kRopeCosSin, cfg.rotaryDim);
47	}
48	
49	TensorRegistry buildRegistryForLLM(LLMEngineConfig const& cfg, std::optional<int32_t> specDecodeBaseOutputHiddenDim)
50	{
51	    TensorRegistry reg;
52	
53	    // ---------------------------------------------------------------
54	    // Core I/O tensors (always present)
55	    // ---------------------------------------------------------------
56	
57	    // inputs_embeds: [batch, seq_len, hiddenSize] HALF
58	    reg.addTensor({binding_names::kInputsEmbeds, TensorIO::kInput, nvinfer1::DataType::kHALF,
59	        {sym(&InferenceDims::batch), sym(&InferenceDims::seqLen), fixed(cfg.hiddenSize)}});
60	
61	    // logits: [batch, outputVocabSize] FLOAT for vanilla, or
62	    // [batch, seq_len, outputVocabSize] for SpecDecode. The engine binding
63	    // shape depends on mode, but output address is always set.
64	    // For the registry we use the common 2D shape; SpecDecode resolves via symbolic dims.
65	    reg.addTensor({binding_names::kLogits, TensorIO::kOutput, nvinfer1::DataType::kFLOAT,
66	        {sym(&InferenceDims::batch), fixed(cfg.outputVocabSize)}});
67	
68	    // context_lengths: [batch] INT32
69	    reg.addTensor(
70	        {binding_names::kContextLengths, TensorIO::kInput, nvinfer1::DataType::kINT32, {sym(&InferenceDims::batch)}});
71	
72	    // last_token_ids: [batch, select_len] INT64 — always [batch, 1] for vanilla, varies for SpecDecode.
73	    reg.addTensor({binding_names::kLastTokenIds, TensorIO::kInput, nvinfer1::DataType::kINT64,
74	        {sym(&InferenceDims::batch), sym(&InferenceDims::selectLen)}});
75	
76	    // kvcache_start_index: [start_index_len] INT32. The engine's context profile
77	    // uses shape [0] as a sentinel for "initial prefill of an empty KV cache";
78	    // chunked prefill, decode, and verification use [batch] start offsets.
79	    // InferenceDims::startIndexLen carries this per-phase: prefillDims sets it to 0
80	    // when kvCacheAllEmpty, else batch; all other recipes
81	    // set it to batch. Shape 0 is engine-valid here — TRT reads 0 bytes from
82	    // the bound address and the engine branches to the initial-prefill path.
83	    reg.addTensor({binding_names::kKVCacheStartIndex, TensorIO::kInput, nvinfer1::DataType::kINT32,
84	        {sym(&InferenceDims::startIndexLen)}});
85	
86	    if (cfg.useVisionBidirectionalAttention)
87	    {
88	        reg.addTensor({binding_names::kVisionBlockIds, TensorIO::kInput, nvinfer1::DataType::kINT32,
89	            {sym(&InferenceDims::batch), sym(&InferenceDims::seqLen)}});
90	    }
91	
92	    // RoPE cache inputs: single binding for single-RoPE models, explicit
93	    // sliding/full bindings for mixed-attention dual-RoPE models.
94	    // For non-MRope, rope_batch is always 1 (TRT broadcasts); for MRope, rope_batch = activeBatchSize.
95	    addRopeTensorSpecs(reg, cfg);
96	
97	    // ---------------------------------------------------------------
98	    // Per-layer KV / recurrent / conv state (hybrid routing by layer_types)
99	    // ---------------------------------------------------------------
100	    //
101	    // Walk the absolute decoder-layer indices and emit one spec per layer.
102	    // For attention layers we use `cfg.kvLayerConfigs[localAttnIdx]` so a model
103	    // with heterogeneous head configs (Gemma4, Qwen3-Next, etc.) gets the
104	    // correct per-layer shape. The %d suffix in the binding name is always a
105	    // LOCAL index (0..numAttn-1 for attention, 0..numMamba-1 for recurrent).
106	    int32_t localAttnIdx = 0;
107	    int32_t localMambaIdx = 0;
108	    for (int32_t absIdx = 0; absIdx < static_cast<int32_t>(cfg.layerTypes.size()); ++absIdx)
109	    {
110	        if (cfg.layerTypes[absIdx] == rt::HybridCacheManager::LayerType::kAttention)
111	        {
112	            auto const& lc = cfg.kvLayerConfigs[localAttnIdx];
113	            auto addKVCacheTensor = [&](char const* tmpl, TensorIO io, std::vector<ShapeDim> const& shape) {
114	                reg.addTensor({std::string(tmpl) + "_" + std::to_string(localAttnIdx), io, cfg.kvCacheDtype, shape});
115	            };
116	            // Plugin: combined KV, 5D [batch, 2, numKVHeads, kv_len, headDim]
117	            std::vector<ShapeDim> const shape{sym(&InferenceDims::batch), fixed(2), fixed(lc.numKVHeads),
118	                sym(&InferenceDims::kvLen), fixed(lc.headDim)};
119	            addKVCacheTensor(binding_names::kPastKeyValuesTemplate, TensorIO::kInput, shape);
120	            addKVCacheTensor(binding_names::kPresentKeyValuesTemplate, TensorIO::kOutput, shape);
121	            ++localAttnIdx;
122	        }
123	        else // kMamba
124	        {
125	            auto addMambaTensor
126	                = [&](char const* tmpl, TensorIO io, nvinfer1::DataType dtype, std::vector<ShapeDim> const& shape) {
127	                      reg.addTensor({std::string(tmpl) + "_" + std::to_string(localMambaIdx), io, dtype, shape});
128	                  };
129	            // recurrent_state_%d: [batch, recurrentStateNumHeads, recurrentStateHeadDim, recurrentStateSize]
130	            std::vector<ShapeDim> const recShape{sym(&InferenceDims::batch), fixed(cfg.recurrentStateNumHeads),
131	                fixed(cfg.recurrentStateHeadDim), fixed(cfg.recurrentStateSize)};
132	            addMambaTensor(binding_names::kRecurrentStateTemplate, TensorIO::kInput, cfg.recurrentStateDtype, recShape);
133	            addMambaTensor(
134	                binding_names::kPresentRecurrentStateTemplate, TensorIO::kOutput, cfg.recurrentStateDtype, recShape);
135	            // conv_state_%d: [batch, convDim, convKernel]
136	            std::vector<ShapeDim> const convShape{
137	                sym(&InferenceDims::batch), fixed(cfg.convDim), fixed(cfg.convKernel)};
138	            addMambaTensor(binding_names::kConvStateTemplate, TensorIO::kInput, cfg.convStateDtype, convShape);
139	            addMambaTensor(binding_names::kPresentConvStateTemplate, TensorIO::kOutput, cfg.convStateDtype, convShape);
140	
141	            // Hybrid MTP/DFlash base only: per-layer intermediate state outputs
142	            // written during prefill/verification so accepted recurrent/conv
143	            // state snapshots can be committed after speculative verification.
144	            //
145	            // intermediate_recurrent_state_%d: [batch, seqLen, recurrentNumHeads, recurrentHeadDim, recurrentStateSize]
146	            // intermediate_conv_state_%d:      [batch, seqLen, convDim, convKernel]
147	            if (cfg.specDecodeType == SpecDecodeMode::kMTP || cfg.specDecodeType == SpecDecodeMode::kDFlash)
148	            {
149	                std::vector<ShapeDim> const interRecShape{sym(&InferenceDims::batch), sym(&InferenceDims::seqLen),
150	                    fixed(cfg.recurrentStateNumHeads), fixed(cfg.recurrentStateHeadDim), fixed(cfg.recurrentStateSize)};
151	                addMambaTensor(binding_names::kIntermediateRecurrentStateTemplate, TensorIO::kOutput,
152	                    cfg.recurrentStateDtype, interRecShape);
153	                if (cfg.convDim > 0 && cfg.convKernel > 0)
154	                {
155	                    std::vector<ShapeDim> const interConvShape{sym(&InferenceDims::batch), sym(&InferenceDims::seqLen),
156	                        fixed(cfg.convDim), fixed(cfg.convKernel)};
157	                    addMambaTensor(binding_names::kIntermediateConvStateTemplate, TensorIO::kOutput, cfg.convStateDtype,
158	                        interConvShape);
159	                }
160	            }
161	            ++localMambaIdx;
162	        }
163	    }
164	
165	    // ---------------------------------------------------------------
166	    // Deepstack (Qwen3-VL / Qwen3-Omni)
167	    // ---------------------------------------------------------------
168	    if (cfg.numDeepstackFeatures > 0)
169	    {
170	        // deepstack_embeds_%d: [batch, seq_len, hiddenSize] HALF — one per feature.
171	        // DeepstackBinding swaps the backing tensor (real per-request buffer
172	        // vs. shared zero buffer) between prefill and non-prefill phases.
173	        reg.addTensor({std::string(binding_names::kDeepstackEmbedsTemplate) + "_%d", TensorIO::kInput,
174	            nvinfer1::DataType::kHALF, {sym(&InferenceDims::batch), sym(&InferenceDims::seqLen), fixed(cfg.hiddenSize)},
175	            /*perLayer=*/cfg.numDeepstackFeatures});
176	    }
177	
178	    // ---------------------------------------------------------------
179	    // SpecDecode verification bindings (base engine side)
180	    // ---------------------------------------------------------------
181	    if (cfg.isSpecDecodeBase)
182	    {
183	        // hidden_states: output, [batch, outputHiddenDim] for vanilla decode,
184	        // or [batch, seq_len, outputHiddenDim] for prefill/verification — use symbolic.
185	        // The concrete output hidden dim is strategy-specific and is consolidated
186	        // in DeploymentConfig::specDecode.
187	        int32_t const baseOutputHiddenDim = specDecodeBaseOutputHiddenDim.value_or(cfg.hiddenSize * 3);
188	        reg.addTensor({binding_names::kOutputHiddenStates, TensorIO::kOutput, nvinfer1::DataType::kHALF,
189	            {sym(&InferenceDims::batch), fixed(baseOutputHiddenDim)}});
190	
191	        // attention_mask: [batch, attn_seq_len, packed_mask_len] INT32 for proposal verification
192	        // packed_mask_len = divUp(attn_seq_len, 32): each INT32 stores 32 mask bits.
193	        // attn_seq_len is decoupled from seq_len so prefill/decode/reset can pin
194	        // it to 1 (engine then uses standard causal attention) while verify,
195	        // proposal, and accept use the effective proposal size.
196	        reg.addTensor({binding_names::kAttentionMask, TensorIO::kInput, nvinfer1::DataType::kINT32,
197	            {sym(&InferenceDims::batch), sym(&InferenceDims::attnMaskSeqLen), sym(&InferenceDims::packedMaskLen)}});
198	
199	        // attention_pos_id: [batch, attn_seq_len] INT32
200	        reg.addTensor({binding_names::kAttentionPosId, TensorIO::kInput, nvinfer1::DataType::kINT32,
201	            {sym(&InferenceDims::batch), sym(&InferenceDims::attnMaskSeqLen)}});
202	
203	        if ((cfg.specDecodeType == SpecDecodeMode::kMTP || cfg.specDecodeType == SpecDecodeMode::kDFlash)
204	            && cfg.numLinearAttnLayers > 0)
205	        {
206	            reg.addTensor({binding_names::kSpecVerifyPhaseMarker, TensorIO::kInput, nvinfer1::DataType::kINT32,
207	                {sym(&InferenceDims::specVerifyPhaseLen)}});
208	        }
209	    }
210	
211	    // ---------------------------------------------------------------
212	    // LoRA
213	    // ---------------------------------------------------------------
214	    // LoRA bindings are dynamic (enumerated from the engine). The registry
215	    // builder cannot know the exact tensor names at compile time because they
216	    // depend on which model layers have LoRA adapters. LoRA tensors are handled
217	    // separately by the EngineExecutor via engine introspection (getLoraWeightsTensorNames).
218	    // Therefore we intentionally skip LoRA here.
219	
220	    return reg;
221	}
222	
223	TensorRegistry buildRegistryForSpecDecodeDraft(DeploymentConfig const& bundle)
224	{
225	    check::check(bundle.draft.has_value(), "buildRegistryForSpecDecodeDraft: bundle.draft must be set");
226	    check::check(bundle.specConfig.has_value(), "buildRegistryForSpecDecodeDraft: bundle.specConfig must be set");
227	    TensorRegistry reg;
228	
229	    LLMEngineConfig const& cfg = *bundle.draft;
230	    int32_t const draftHiddenSize = bundle.specConfig->draftHiddenSize;
231	    int32_t const baseOutputHiddenDim = bundle.specConfig->baseOutputHiddenDim;
232	    int32_t const draftVocabSize = cfg.outputVocabSize;
233	
234	    // ---------------------------------------------------------------
235	    // Core I/O tensors
236	    // ---------------------------------------------------------------
237	
238	    // inputs_embeds: [batch, seq_len, draftHiddenSize] HALF
239	    reg.addTensor({binding_names::kInputsEmbeds, TensorIO::kInput, nvinfer1::DataType::kHALF,
240	        {sym(&InferenceDims::batch), sym(&InferenceDims::seqLen), fixed(draftHiddenSize)}});
241	
242	    // hidden_states_input (base model hidden states): [batch, seq_len, baseOutputHiddenDim] HALF
243	    reg.addTensor({binding_names::kBaseModelHiddenStates, TensorIO::kInput, nvinfer1::DataType::kHALF,
244	        {sym(&InferenceDims::batch), sym(&InferenceDims::seqLen), fixed(baseOutputHiddenDim)}});
245	
246	    // hidden_states_from_draft (draft model hidden states): [batch, seq_len, draftHiddenSize] HALF
247	    reg.addTensor({binding_names::kDraftModelHiddenStates, TensorIO::kInput, nvinfer1::DataType::kHALF,
248	        {sym(&InferenceDims::batch), sym(&InferenceDims::seqLen), fixed(draftHiddenSize)}});
249	
250	    // last_token_ids: [batch, select_len] INT64
251	    reg.addTensor({binding_names::kLastTokenIds, TensorIO::kInput, nvinfer1::DataType::kINT64,
252	        {sym(&InferenceDims::batch), sym(&InferenceDims::selectLen)}});
253	
254	    // context_lengths: [batch] INT32
255	    reg.addTensor(
256	        {binding_names::kContextLengths, TensorIO::kInput, nvinfer1::DataType::kINT32, {sym(&InferenceDims::batch)}});
257	
258	    // kvcache_start_index: [start_index_len] INT32. Draft engine always uses
259	    // the plugin path: shape [0] sentinel during round-0 prefill (empty draft
260	    // KV cache); [batch] for proposal / accept.
261	    reg.addTensor({binding_names::kKVCacheStartIndex, TensorIO::kInput, nvinfer1::DataType::kINT32,
262	        {sym(&InferenceDims::startIndexLen)}});
263	
264	    // RoPE cache inputs: single binding for single-RoPE models, explicit
265	    // sliding/full bindings for mixed-attention dual-RoPE models.
266	    addRopeTensorSpecs(reg, cfg);
267	
268	    // attention_mask: [batch, attn_seq_len, packed_mask_len] INT32 — tree decoding mask
269	    // packed_mask_len = divUp(attn_seq_len, 32): each INT32 stores 32 mask bits.
270	    // attn_seq_len is decoupled from seq_len so prefill/decode/reset can pin
271	    // it to 1 (engine then uses standard causal attention) while tree
272	    // verify/proposal/accept use the effective tree size.
273	    reg.addTensor({binding_names::kAttentionMask, TensorIO::kInput, nvinfer1::DataType::kINT32,
274	        {sym(&InferenceDims::batch), sym(&InferenceDims::attnMaskSeqLen), sym(&InferenceDims::packedMaskLen)}});
275	
276	    // attention_pos_id: [batch, attn_seq_len] INT32
277	    reg.addTensor({binding_names::kAttentionPosId, TensorIO::kInput, nvinfer1::DataType::kINT32,
278	        {sym(&InferenceDims::batch), sym(&InferenceDims::attnMaskSeqLen)}});
279	
280	    // ---------------------------------------------------------------
281	    // Outputs
282	    // ---------------------------------------------------------------
283	
284	    // logits: [batch, draftVocabSize] FLOAT
285	    reg.addTensor({binding_names::kLogits, TensorIO::kOutput, nvinfer1::DataType::kFLOAT,
286	        {sym(&InferenceDims::batch), fixed(draftVocabSize)}});
287	
288	    // hidden_states (output): [batch, draftHiddenSize] HALF
289	    reg.addTensor({binding_names::kOutputHiddenStates, TensorIO::kOutput, nvinfer1::DataType::kHALF,
290	        {sym(&InferenceDims::batch), fixed(draftHiddenSize)}});
291	
292	    // ---------------------------------------------------------------
293	    // KV cache (draft engine always uses plugin path)
294	    // ---------------------------------------------------------------
295	    //
296	    // Draft engines today are uniform (single numKVHeads / headDim across all
297	    // attention layers), and their `layerTypes` are broadcast from
298	    // `numAttentionLayers` by `parseDraftEngineConfig`. We still walk per-layer
299	    // so this stays forward-compatible with future heterogeneous draft configs.
300	    {
301	        int32_t localAttnIdx = 0;
302	        for (int32_t absIdx = 0; absIdx < static_cast<int32_t>(cfg.layerTypes.size()); ++absIdx)
303	        {
304	            if (cfg.layerTypes[absIdx] != rt::HybridCacheManager::LayerType::kAttention)
305	            {
306	                // Current draft engines are not expected to contain Mamba layers. If a
307	                // future config exercises this branch it's a config error, not a
308	                // registry-builder concern.
309	                continue;
310	            }
311	            auto const& lc = cfg.kvLayerConfigs[localAttnIdx];
312	            std::vector<ShapeDim> const shape{sym(&InferenceDims::batch), fixed(2), fixed(lc.numKVHeads),
313	                sym(&InferenceDims::kvLen), fixed(lc.headDim)};
314	            auto addKVCacheTensor = [&](char const* tmpl, TensorIO io) {
315	                reg.addTensor({std::string(tmpl) + "_" + std::to_string(localAttnIdx), io, cfg.kvCacheDtype, shape});
316	            };
317	            addKVCacheTensor(binding_names::kPastKeyValuesTemplate, TensorIO::kInput);
318	            addKVCacheTensor(binding_names::kPresentKeyValuesTemplate, TensorIO::kOutput);
319	            ++localAttnIdx;
320	        }
321	    }
322	
323	    return reg;
324	}
325	
326	TensorRegistry buildRegistryForDFlashDraft(DeploymentConfig const& bundle)
327	{
328	    check::check(bundle.draft.has_value(), "buildRegistryForDFlashDraft: bundle.draft must be set");
329	    check::check(bundle.specConfig.has_value(), "buildRegistryForDFlashDraft: bundle.specConfig must be set");
330	
331	    TensorRegistry reg;
332	    LLMEngineConfig const& cfg = *bundle.draft;
333	    int32_t const draftHiddenSize = bundle.specConfig->draftHiddenSize;
334	    int32_t const baseOutputHiddenDim = bundle.specConfig->baseOutputHiddenDim;
335	    int32_t const draftVocabSize = cfg.outputVocabSize;
336	
337	    // inputs_embeds: [batch, seq_len, draftHiddenSize] HALF
338	    reg.addTensor({binding_names::kInputsEmbeds, TensorIO::kInput, nvinfer1::DataType::kHALF,
339	        {sym(&InferenceDims::batch), sym(&InferenceDims::seqLen), fixed(draftHiddenSize)}});
340	
341	    // dflash_target_hidden_concat: [batch, selectLen, baseOutputHiddenDim] HALF — target hidden delta
342	    reg.addTensor({binding_names::kDFlashTargetHiddenConcat, TensorIO::kInput, nvinfer1::DataType::kHALF,
343	        {sym(&InferenceDims::batch), sym(&InferenceDims::selectLen), fixed(baseOutputHiddenDim)}});
344	
345	    // logits: [batch, seq_len, draftVocabSize] FLOAT
346	    reg.addTensor({binding_names::kLogits, TensorIO::kOutput, nvinfer1::DataType::kFLOAT,
347	        {sym(&InferenceDims::batch), sym(&InferenceDims::seqLen), fixed(draftVocabSize)}});
348	
349	    // context_lengths: [batch] INT32
350	    reg.addTensor(
351	        {binding_names::kContextLengths, TensorIO::kInput, nvinfer1::DataType::kINT32, {sym(&InferenceDims::batch)}});
352	
353	    // kvcache_start_index: [startIndexLen] INT32
354	    reg.addTensor({binding_names::kKVCacheStartIndex, TensorIO::kInput, nvinfer1::DataType::kINT32,
355	        {sym(&InferenceDims::startIndexLen)}});
356	
357	    // dflash_delta_lengths: [batch] INT32 — per-batch delta lengths for multi-batch
358	    reg.addTensor({binding_names::kDFlashDeltaLengths, TensorIO::kInput, nvinfer1::DataType::kINT32,
359	        {sym(&InferenceDims::batch)}});
360	
361	    // rope_rotary_cos_sin: [ropeBatch, kvLen, rotaryDim] FLOAT
362	    reg.addTensor({binding_names::kRopeCosSin, TensorIO::kInput, nvinfer1::DataType::kFLOAT,
363	        {sym(&InferenceDims::ropeBatch), sym(&InferenceDims::kvLen), fixed(cfg.rotaryDim)}});
364	
365	    // attention_mask: [batch, attnMaskSeqLen, packedMaskLen] INT32
366	    reg.addTensor({binding_names::kAttentionMask, TensorIO::kInput, nvinfer1::DataType::kINT32,
367	        {sym(&InferenceDims::batch), sym(&InferenceDims::attnMaskSeqLen), sym(&InferenceDims::packedMaskLen)}});
368	
369	    // attention_pos_id: [batch, attnMaskSeqLen] INT32
370	    reg.addTensor({binding_names::kAttentionPosId, TensorIO::kInput, nvinfer1::DataType::kINT32,
371	        {sym(&InferenceDims::batch), sym(&InferenceDims::attnMaskSeqLen)}});
372	
373	    // Per-layer KV cache (plugin path: combined KV)
374	    {
375	        int32_t localAttnIdx = 0;
376	        for (int32_t absIdx = 0; absIdx < static_cast<int32_t>(cfg.layerTypes.size()); ++absIdx)
377	        {
378	            if (cfg.layerTypes[absIdx] != rt::HybridCacheManager::LayerType::kAttention)
379	            {
380	                continue;
381	            }
382	            auto const& lc = cfg.kvLayerConfigs[localAttnIdx];
383	            std::vector<ShapeDim> const shape{sym(&InferenceDims::batch), fixed(2), fixed(lc.numKVHeads),
384	                sym(&InferenceDims::kvLen), fixed(lc.headDim)};
385	            auto addKVCacheTensor = [&](char const* tmpl, TensorIO io) {
386	                reg.addTensor({std::string(tmpl) + "_" + std::to_string(localAttnIdx), io, cfg.kvCacheDtype, shape});
387	            };
388	            addKVCacheTensor(binding_names::kPastKeyValuesTemplate, TensorIO::kInput);
389	            addKVCacheTensor(binding_names::kPresentKeyValuesTemplate, TensorIO::kOutput);
390	            ++localAttnIdx;
391	        }
392	    }
393	
394	    return reg;
395	}
396	
397	TensorRegistry buildRegistryForGemma4MTPDraft(DeploymentConfig const& bundle)
398	{
399	    check::check(bundle.draft.has_value(), "buildRegistryForGemma4MTPDraft: bundle.draft must be set");
400	    check::check(bundle.specConfig.has_value(), "buildRegistryForGemma4MTPDraft: bundle.specConfig must be set");
401	    check::check(bundle.specDecodeMode() == SpecDecodeMode::kGemma4MTP,
402	        "buildRegistryForGemma4MTPDraft requires spec_decode_type=gemma4_mtp");
403	
404	    TensorRegistry reg;
405	    LLMEngineConfig const& draftCfg = *bundle.draft;
406	    int32_t const baseOutputHiddenDim = bundle.specConfig->baseOutputHiddenDim;
407	    int32_t const draftVocabSize = draftCfg.outputVocabSize;
408	
409	    // inputs_embeds: [B, 1, Hb] target/base embedding table output.
410	    reg.addTensor({binding_names::kInputsEmbeds, TensorIO::kInput, nvinfer1::DataType::kHALF,
411	        {sym(&InferenceDims::batch), sym(&InferenceDims::seqLen), fixed(baseOutputHiddenDim)}});
412	
413	    // hidden_states_input: [B, 1, Hb] target hidden seed or assistant feedback hidden.
414	    reg.addTensor({binding_names::kBaseModelHiddenStates, TensorIO::kInput, nvinfer1::DataType::kHALF,
415	        {sym(&InferenceDims::batch), sym(&InferenceDims::seqLen), fixed(baseOutputHiddenDim)}});
416	
417	    // context_lengths: [B] target KV lengths.
418	    reg.addTensor(
419	        {binding_names::kContextLengths, TensorIO::kInput, nvinfer1::DataType::kINT32, {sym(&InferenceDims::batch)}});
420	
421	    addRopeTensorSpecs(reg, draftCfg);
422	
423	    // logits: [B, vocab] full-logits correctness path.
424	    reg.addTensor({binding_names::kLogits, TensorIO::kOutput, nvinfer1::DataType::kFLOAT,
425	        {sym(&InferenceDims::batch), fixed(draftVocabSize)}});
426	
427	    // hidden_states: [B, 1, Hb] assistant feedback hidden in target backbone space.
428	    reg.addTensor({binding_names::kOutputHiddenStates, TensorIO::kOutput, nvinfer1::DataType::kHALF,
429	        {sym(&InferenceDims::batch), sym(&InferenceDims::seqLen), fixed(baseOutputHiddenDim)}});
430	
431	    for (auto const& entry : draftCfg.gemma4MTPKVSharingMap)
432	    {
433	        check::check(entry.assistantLayerIdx >= 0 && entry.assistantLayerIdx < draftCfg.numAttentionLayers,
434	            "buildRegistryForGemma4MTPDraft: invalid assistant layer index");
435	        check::check(entry.targetAttentionLayerIdx >= 0
436	                && entry.targetAttentionLayerIdx < static_cast<int32_t>(bundle.base.kvLayerConfigs.size()),
437	            "buildRegistryForGemma4MTPDraft: invalid target attention layer index");
438	
439	        auto const& targetKV = bundle.base.kvLayerConfigs[entry.targetAttentionLayerIdx];
440	        std::vector<ShapeDim> const shape{sym(&InferenceDims::batch), fixed(2), fixed(targetKV.numKVHeads),
441	            sym(&InferenceDims::kvLen), fixed(targetKV.headDim)};
442	        reg.addTensor({binding_names::formatKVCacheName(entry.assistantLayerIdx, /*isPast=*/true), TensorIO::kInput,
443	            bundle.base.kvCacheDtype, shape});
444	    }
445	
446	    return reg;
447	}
448	
449	} // namespace rt
450	} // namespace trt_edgellm
